type State =
  | { kind: "loading"; requestId: number }
  | { kind: "success"; requestId: number; data: string[] };
function resolve(state: State, requestId: number, data: string[]): State {
  if (state.kind !== "loading" || state.requestId !== requestId) {
    return state;
  }
  return { kind: "success", requestId, data };
}
const active: State = { kind: "loading", requestId: 8 };
console.log(resolve(active, 7, ["old"]) === active);

type State = {kind:"idle"} | {kind:"loading"; requestId:number}
  | {kind:"success"; requestId:number; data:string[]}
  | {kind:"error"; requestId:number; message:string}
  | {kind:"cancelled"; requestId:number};
type Action = {type:"start"; requestId:number} | {type:"resolve"; requestId:number; data:string[]}
  | {type:"reject"; requestId:number; message:string} | {type:"cancel"; requestId:number};
function reduce(state: State, action: Action): State {
  if (action.type === "start") return {kind:"loading", requestId:action.requestId};
  if (state.kind !== "loading" || state.requestId !== action.requestId) return state;
  if (action.type === "resolve") return {kind:"success", requestId:action.requestId, data:action.data};
  if (action.type === "reject") return {kind:"error", requestId:action.requestId, message:action.message};
  return {kind:"cancelled", requestId:action.requestId};
}
const loading = reduce({kind:"idle"}, {type:"start", requestId:2});
const cancelled = reduce(loading, {type:"cancel", requestId:2});
console.log(reduce(cancelled, {type:"resolve", requestId:2, data:["late"]}) === cancelled);
console.log(reduce(loading, {type:"resolve", requestId:1, data:["old"]}) === loading);

