      <label>Search <input value={query} onChange={e => setQuery(e.target.value)} /></label>
      <button onClick={() => search(false)}>Search</button>
      <button onClick={() => search(true)}>Fail</button>
      {status === "loading" && <p>Searching…</p>}
      {status === "error" && <p role="alert">{error}</p>}
      {status === "success" && results.length === 0 && <p>No results.</p>}
      {status === "success" && <ul>
        {results.map(item => <li key={item}>{item}</li>)}
      </ul>}
    </main>
  );
}

function App() {
  const [query, setQuery] = React.useState("");
  const [results, setResults] = React.useState([]);
  const [status, setStatus] = React.useState("idle");
  const [error, setError] = React.useState("");
  const latest = React.useRef(0);
  function search(fails) {
    const id = ++latest.current;
    const searched = query;
    setStatus("loading");
    setError("");
    setTimeout(() => {
      if (id !== latest.current) return;
      if (fails) {
        setError("Search failed. Try again.");
        setStatus("error");
        return;
      }
      setResults(searched ? [`Result for ${searched}`] : []);
      setStatus("success");
    }, searched.includes("slow") ? 80 : 10);
  }
  return (
    <main>
      <label>Search books <input value={query} onChange={e => setQuery(e.target.value)} /></label>
      <button onClick={() => search(false)}>Search</button>
      <button onClick={() => search(true)}>Fail search</button>
      {status === "loading" && <p>Searching…</p>}
      {status === "error" && <p role="alert">{error}</p>}
      {status === "success" && results.length === 0 && <p>No results.</p>}
      {status === "success" && <ul>
        {results.map(item => <li key={item}>{item}</li>)}
      </ul>}
    </main>
  );
}

