function createHistory(initial) {
  let versions = [initial];
  let cursor = 0;
  return {
    current: () => versions[cursor],
    edit(text) {
      if (text === versions[cursor]) return text;
      versions = versions.slice(0, cursor + 1);
      versions.push(text);
      cursor = versions.length - 1;
      return versions[cursor];
    },
    undo() { cursor = Math.max(0, cursor - 1); return versions[cursor]; },
    redo() { cursor = Math.min(versions.length - 1, cursor + 1); return versions[cursor]; }
  };
}
