function taskReducer(tasks, action) {
  if (action.type === "add") {
    return tasks.some(task => task.id === action.id) ? tasks : [...tasks, {id:action.id, done:false}];
  }
  if (action.type === "toggle") return tasks.map(task => task.id === action.id ? {...task, done:!task.done} : task);
  return tasks;
}
function App() {
  const [tasks, dispatch] = React.useReducer(taskReducer, []);
  return <main>
    <button onClick={() => dispatch({type:"add", id:"read"})}>Add Read</button>
    {tasks.map(task => <button key={task.id} onClick={() => dispatch({type:"toggle", id:task.id})}>
      {task.id}: {task.done ? "done" : "unfinished"}
    </button>)}
  </main>;
}

