class PanelBoundary extends React.Component {
  constructor(props) {super(props); this.state = {failed:false};}
  static getDerivedStateFromError() {return {failed:true};}
  render() {return this.state.failed ? <p>Panel unavailable</p> : this.props.children;}
}
function Panel({broken}) {
  if (broken) throw new Error("Panel failed");
  return <p>Panel ready</p>;
}
function App() {
  const [broken, setBroken] = React.useState(false);
  const [version, setVersion] = React.useState(0);
  return <main><h1>Dashboard</h1>
    <button onClick={() => setBroken(true)}>Break panel</button>
    <button onClick={() => {setBroken(false); setVersion(v => v + 1);}}>Reset panel</button>
    <PanelBoundary key={version}><Panel broken={broken} /></PanelBoundary>
  </main>;
}

